class Solution:
    def countGoodSubstrings(self, s: str) -> int:
        return sum(1 for i in range(len(s)-2) if len(set(s[i:i+3]))) == 3)

shortest-distance-to-target-string-in-a-:
class Solution:
    def closetTarget(self, words: List[str], target: str, startIndex: int) -> int:
        n = len(words)
        best = float('inf')
        for i in range(n):
            if words[i] == target:
                d = abs(startIndex-i)
                d = min(d, n-d)
                best = min(best, d)
        return best if best != float('inf') else -1

minimum-number-of-chairs-in-a-waiting-ro:
class Solution:
    def minimumChairs(self, s: str) -> int:
        ans = cur = 0
        for c in s:
            cur += 1 if c == 'E' else -1
            ans = max(ans, cur)
        return ans
